function mulberry32(seed) {
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pick(rand, list) {
  return list[Math.floor(rand() * list.length)];
}

function buildFaithfulSvg(seedValue) {
  if (!sourceSvg) return '';

  const rand = mulberry32(seedValue);
  const hue = Math.floor(rand() * 14) - 7;
  const x = Math.floor(rand() * 34) - 17;
  const y = Math.floor(rand() * 34) - 17;

  return sourceSvg
    .replace(/<\?xml[^>]*>/, '')
    .replace('<svg ', `<svg style="filter:hue-rotate(${hue}deg)" `)
    .replace('<g id="C_Parts"', `<g transform="translate(${x} ${y})" id="C_Parts"`)
    .replace('<g id="Layer_21"', `<g transform="translate(${-x} ${Math.floor(y / 2)})" id="Layer_21"`)
    .replace('<g id="type_02_copy"', '<g id="type_02_copy"');
}

function render(seedValue = Number(seedInput.value || 1)) {
  const bloomReveal = state.bloom ? 1 : 0.16;
  const nameReveal = state.name ? 1 : 0;
  const flourishReveal = state.flourish ? 1 : 0;
  const svgMarkup = buildFaithfulSvg(seedValue);

  artwork.innerHTML = svgMarkup;
  const svg = artwork.querySelector('svg');
  if (svg) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'Generated artwork');
    svg.style.background = '#ffffff';

    const colorMass = svg.querySelector('#C_Parts');
    const secondaryMass = svg.querySelector('#Layer_21');
    const typeLayer = svg.querySelector('#type_02_copy');

    if (colorMass) colorMass.style.opacity = bloomReveal;
    if (secondaryMass) secondaryMass.style.opacity = bloomReveal;
    if (typeLayer) {
      typeLayer.style.opacity = nameReveal;
      typeLayer.querySelectorAll('g').forEach((group, index) => {
        if (index >= 1) group.style.opacity = flourishReveal;
      });
    }
  }

  document.getElementById('bloomState').textContent = state.bloom;
  document.getElementById('nameState').textContent = state.name;
  document.getElementById('flourishState').textContent = state.flourish;
}

document.querySelectorAll('[data-action]').forEach((button) => {
  button.addEventListener('click', () => {
    const action = button.dataset.action;
    if (action === 'reset') {
      state.bloom = 0;
      state.name = 0;
      state.flourish = 0;
    } else {
      state[action] = 1;
    }
    render();
  });
});

seedInput.addEventListener('input', () => render());
render();
